#!/usr/bin/env python3
"""Generate build/third-party/registry.bzl from Cargo.lock.

Usage:
    cd <project-root>
    python3 build/third-party/tools/gen-registry.py > build/third-party/registry.bzl

Run once (while cargo is available) and commit the result. After that,
registry.bzl is the committed Starlark source of truth — no cargo needed at build time.
"""

import sys
import tomllib
import json
import subprocess
from pathlib import Path

BUILD_SCRIPTS: set[str] = {
    "proc-macro2", "quote", "serde", "serde_json", "serde_derive",
    "serde_core", "syn", "rustversion", "scratch",
    "blake3", "blake3-sys",
    "zstd", "zstd-sys", "zstd-safe",
    "libc", "pkg-config", "cmake", "cc",
    "openssl-sys", "openssl", "ring", "aws-lc-sys", "aws-lc-rs",
    "tikv-jemalloc-sys", "mimalloc-rust-sys", "libsqlite3-sys",
    "schannel", "bzip2-sys", "xz2", "libz-sys", "libz-rs-sys",
    "flate2", "async-compression",
    "onig_sys", "curl-sys", "libgit2-sys",
    "rustls-webpki", "rustls-pki-types",
    "home", "erased-serde",
    "normpath", "uncased",
    "crunchy",
}

PROC_MACROS: set[str] = {
    "serde_derive", "thiserror-impl",
    "nutype_macros", "strum_macros", "async-trait",
    "yoke-derive", "enumset_derive",
    "nonempty-derive",
    "time-macros",
    "async-stream-impl",
    "bytecheck_derive",
    "darling_macro",
    "derive_builder_macro",
    "displaydoc",
    "facet-macros",
    "futures-macro",
    "inherent",
    "kinded_macros",
    "munge_macro",
    "mutants",
    "pear_codegen",
    "pin-project-internal",
    "prost-derive",
    "ptr_meta_derive",
    "ref-cast-impl",
    "rkyv_derive",
    "rustversion",
    "sea-query-derive",
    "snafu-derive",
    "sqlx-macros",
    "tokio-macros",
    "tracing-attributes",
    "wasm-bindgen-macro",
    "windows-implement",
    "windows-interface",
    "zerocopy-derive",
    "zerofrom-derive",
    "zerovec-derive",
}

FEATURES: dict[str, list[str]] = {
    # Crates that gate std/alloc functionality behind feature flags.
    # Buck2 builds with features=[] by default (no-default-features).
    "aho-corasick": ["std"],
    "byteorder": ["std"],
    "crossbeam-channel": ["std"],
    "governor": ["std"],
    "indexmap": ["std"],
    "memchr": ["std"],
    "nom": ["std"],
    "num-traits": ["std"],
    "once_cell": ["std"],
    "rand": ["std", "std_rng"],
    "rand_chacha": ["std"],
    "rand_core": ["getrandom", "std"],
    "regex": ["std", "perf", "unicode"],
    "serde": ["std"],
    "serde_core": ["std"],
    "serde_json": ["std"],
    "time": ["std"],
    "tinyvec": ["alloc"],
    "unicode-bidi": ["std"],
    "url": ["std"],
}


def normalize(name: str) -> str:
    return name.replace("-", "_")


def make_label(name: str, version: str) -> str:
    parts = version.split(".")
    major = parts[0]
    if major == "0" and len(parts) > 1:
        return f"{normalize(name)}-{major}_{parts[1]}"
    return f"{normalize(name)}-{major}"


def parse_cargo_lock(path: Path) -> list[dict]:
    with open(path, "rb") as f:
        data = tomllib.load(f)
    return data.get("package", [])


def load_editions(root: Path) -> dict[str, str]:
    meta_path = root / "target" / "cargo-metadata.json"
    if meta_path.exists():
        with open(meta_path) as f:
            data = json.load(f)
    else:
        result = subprocess.run(
            ["cargo", "metadata", "--format-version=1"],
            capture_output=True, text=True, cwd=str(root),
        )
        if result.returncode != 0:
            print(f"Warning: cargo metadata failed: {result.stderr.strip()}", file=sys.stderr)
            return {}
        data = json.loads(result.stdout)
    return {f"{p['name']}-{p['version']}": p['edition'] for p in data['packages']}


def starlark_str(s: str) -> str:
    escaped = s.replace("\\", "\\\\").replace('"', '\\"')
    return f'"{escaped}"'


def starlark_bool(b: bool) -> str:
    return "True" if b else "False"


def starlark_list(items: list[str]) -> str:
    if not items:
        return "[]"
    return "[" + ", ".join(starlark_str(i) for i in items) + "]"


def generate_registry(packages: list[dict], editions: dict[str, str]) -> str:
    lines: list[str] = []
    out = lines.append

    out("# @generated by build/third-party/tools/gen-registry.py")
    out("# To regenerate: python3 build/third-party/tools/gen-registry.py > build/third-party/registry.bzl")
    out("")
    out("REGISTRY = [")

    name_map: dict[str, dict[str, dict]] = {}
    for pkg in packages:
        name_map.setdefault(pkg["name"], {})[pkg["version"]] = pkg

    registry_pkgs = [p for p in packages if p.get("source", "").startswith("registry+")]

    generated_aliases: set[str] = set()

    for pkg in registry_pkgs:
        name = pkg["name"]
        version = pkg["version"]
        checksum = pkg.get("checksum", "")
        lbl = make_label(name, version)
        edition = editions.get(f"{name}-{version}", "2021")
        has_build = name in BUILD_SCRIPTS
        is_proc = name in PROC_MACROS
        features = FEATURES.get(name, [])

        raw_deps: list[str] = pkg.get("dependencies", [])
        dep_labels: list[str] = []
        for dep_str in raw_deps:
            parts = dep_str.strip().split()
            d_name = parts[0]
            d_ver = parts[1] if len(parts) > 1 else None
            versions = name_map.get(d_name, {})
            if not versions:
                continue
            if d_ver:
                ver = d_ver
            elif len(versions) == 1:
                ver = next(iter(versions))
            else:
                continue
            dep = versions.get(ver)
            if dep and dep.get("source") and not dep["source"].startswith("git+"):
                dep_labels.append(f":{make_label(d_name, ver)}")
        dep_labels = sorted(set(dep_labels))

        safe = normalize(name)
        alias = safe not in generated_aliases
        if alias:
            generated_aliases.add(safe)

        out("    {")
        out(f'        "name": {starlark_str(name)},')
        out(f'        "version": {starlark_str(version)},')
        out(f'        "sha256": {starlark_str(checksum)},')
        out(f'        "edition": {starlark_str(edition)},')
        out(f'        "label": {starlark_str(lbl)},')
        out(f'        "alias": {starlark_bool(alias)},')
        out(f'        "deps": {starlark_list(dep_labels)},')
        out(f'        "features": {starlark_list(features)},')
        out(f'        "build_script": {starlark_bool(has_build)},')
        out(f'        "proc_macro": {starlark_bool(is_proc)},')
        out("    },")

    out("]")
    return "\n".join(lines) + "\n"


def main() -> None:
    root = Path(__file__).parent.parent.parent.parent.resolve()
    lock_path = root / "Cargo.lock"
    if not lock_path.exists():
        print(f"Error: Cargo.lock not found at {lock_path}", file=sys.stderr)
        sys.exit(1)
    packages = parse_cargo_lock(lock_path)
    editions = load_editions(root)
    print(generate_registry(packages, editions), end="")


if __name__ == "__main__":
    main()
